// I2C LCD ekranlı termometre: DHT22 sıcaklık ve nemi 4 kabloyla bağlanan LCD'de gösterir.
// Paralel LCD 6 veri kablosu ister; I2C sürümü yalnız SDA ve SCL (+ VCC, GND) kullanır.
// LCD adresi çoğunlukla 0x27; bazı kartlarda 0x3F. Çalışmazsa adresi değiştir.
#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <DHT.h>

const int DHT_PIN = 2;
LiquidCrystal_I2C lcd(0x27, 16, 2);
DHT dht(DHT_PIN, DHT22);

byte derece[8] = {0b01100, 0b10010, 0b10010, 0b01100, 0, 0, 0, 0};

void setup() {
  Serial.begin(9600);
  lcd.init();
  lcd.backlight();
  lcd.createChar(0, derece);
  dht.begin();
  lcd.setCursor(0, 0);
  lcd.print("Termometre");
}

void loop() {
  float sicaklik = dht.readTemperature();
  float nem = dht.readHumidity();
  if (isnan(sicaklik)) {
    lcd.setCursor(0, 1);
    lcd.print("Sensor okunamadi");
    delay(1000);
    return;
  }
  lcd.setCursor(0, 1);
  lcd.print("Isi ");
  lcd.print(sicaklik, 1);
  lcd.write(byte(0));
  lcd.print("C Nem ");
  lcd.print((int)nem);
  lcd.print("%  ");
  Serial.print("Sicaklik: ");
  Serial.print(sicaklik, 1);
  Serial.print(" C  Nem: ");
  Serial.print((int)nem);
  Serial.println(" %");
  delay(1000);
}
